#!/usr/bin/env bash
# W1 rebuild: thinking-mode harness + probing. Run from TokenGuard repo root.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing W1 thinking harness..."
decode "src/tokenguard/llm/thinking.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_w1_thinking.py" << 'B64EOF'

B64EOF
decode "tests/test_thinking.py" << 'B64EOF'

B64EOF
echo ""
echo "Installed. Verify: python -m pytest tests/test_thinking.py -q"
echo "Then run:"
echo "  python scripts/ntc_w1_thinking.py --model Qwen/Qwen3-4B --benchmark math500 --limit 60 --max-think 6144 --batch 16 --tp-size 1"